  q2 := jsonb_build_array(
jsonb_build_object('number',27,'question',E'다음 우리말에 맞는 영어 문장을 고르시오.\n\n나는 그 경기를 봤는데, 정말 흥미진진했다.','type','mcq','options',jsonb_build_array(E'I watched the game, that was really exciting.',E'I watched the game, what was really exciting.',E'I watched the game, which was really exciting.',E'I watched the game, which it was really exciting.',E'I watched the game, who was really exciting.'),'answer',E'3','explanation',E'사물(the game) 계속적 용법 → which. that/what/who 불가, which it 중복'),
jsonb_build_object('number',28,'question',E'다음 우리말에 맞는 영어 문장을 고르시오.\n\n그는 새 아파트로 이사했는데, 그것은 공원 바로 옆에 있다.','type','mcq','options',jsonb_build_array(E'He moved to a new apartment, that is right next to the park.',E'He moved to a new apartment, which right next to the park.',E'He moved to a new apartment, who is right next to the park.',E'He moved to a new apartment, which is right next to the park.',E'He moved to a new apartment, what is right next to the park.'),'answer',E'4','explanation',E'apartment=사물 → which + be동사 is 필요'),
jsonb_build_object('number',29,'question',E'다음 우리말에 맞는 영어 문장을 고르시오.\n\n나는 그 소설을 다 읽었는데, 그것은 나를 한참 생각하게 만들었다.','type','mcq','options',jsonb_build_array(E'I finished the novel, that made me think for a long time.',E'I finished the novel, which it made me think for a long time.',E'I finished the novel, which made me think for a long time.',E'I finished the novel, what made me think for a long time.',E'I finished the novel, who made me think for a long time.'),'answer',E'3','explanation',E'the novel=사물 → which'),
jsonb_build_object('number',30,'question',E'다음 우리말에 맞는 영어 문장을 고르시오.\n\n모두가 그를 좋아하는데, 그가 항상 친절하고 정직하기 때문이다.','type','mcq','options',jsonb_build_array(E'Everybody likes him, which is always kind and honest.',E'Everybody likes him, that is always kind and honest.',E'Everybody likes him, who is always kind and honest.',E'Everybody likes him, whom is always kind and honest.',E'Everybody likes him, and which is always kind and honest.'),'answer',E'3','explanation',E'him=사람 + 주격 → who. whom은 목적격'),
jsonb_build_object('number',31,'question',E'다음 우리말에 맞는 영어 문장을 모두 고르시오. (정답 2개)\n\n나는 그 영화를 봤는데, 그것은 실제 이야기를 바탕으로 했다.','type','select_all','options',jsonb_build_array(E'I saw the movie, that was based on a true story.',E'I saw the movie, which was based on a true story.',E'I saw the movie, what was based on a true story.',E'I saw the movie, and it was based on a true story.',E'I saw the movie, which it was based on a true story.'),'answer',jsonb_build_array('2','4'),'explanation',E'② which 계속적 용법 옳음. ④ and it = which와 같은 의미'),
jsonb_build_object('number',32,'question',E'다음 우리말에 맞는 영어 문장을 고르시오.\n\n그녀에게는 남동생이 하나 있는데, 그는 프로 축구 선수가 되고 싶어 한다.','type','mcq','options',jsonb_build_array(E'She has a brother, that wants to become a professional soccer player.',E'She has a brother, which wants to become a professional soccer player.',E'She has a brother, whom wants to become a professional soccer player.',E'She has a brother, who wants to become a professional soccer player.',E'She has a brother, and which wants to become a professional soccer player.'),'answer',E'4','explanation',E'brother=사람 + 주격 → who'),
jsonb_build_object('number',33,'question',E'다음 우리말에 맞는 영어 문장을 고르시오.\n\n우리 아버지는 매일 아침 달리기를 하시는데, 그것이 그를 건강하게 유지시켜 준다.','type','mcq','options',jsonb_build_array(E'My father runs every morning, who keeps him healthy.',E'My father runs every morning, that keeps him healthy.',E'My father runs every morning, what keeps him healthy.',E'My father runs every morning, which it keeps him healthy.',E'My father runs every morning, which keeps him healthy.'),'answer',E'5','explanation',E'앞 문장 전체(달리기 하는 것)가 선행사 → which'),
